import './App.css';
import Navbar from '../Navbar/Navbar';

function App() {
  let Component
  switch (window.location.pathname) {
    case "/":
      Component = App
      break
    case "/about":
      Component = About
      break
    case "/projects":
      Component = Projects
      break
    case "/contact":
      Component = Contact
      break
  }
  return (
    <div className="App glass">
      <Navbar />
      <Component />
    </div>
  );
}

export default App;
